<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import BaseButton from '../../components/ui/BaseButton.vue'; import { useCompanyOnboardingStore } from '../../stores/companyOnboarding'; import { lookupAddress } from '../../services/address.service'; import { digits, maskCep } from '../../utils/validation'
const router = useRouter(); const store = useCompanyOnboardingStore(); const error = ref(''); const loading = ref(false)
async function lookup() { if (digits(store.state.address.zipCode).length !== 8) return; loading.value = true; error.value = ''; try { store.updateAddress(await lookupAddress(store.state.address.zipCode)) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Não foi possível consultar o CEP.' } finally { loading.value = false } }
function next() { const address = store.state.address; error.value = !address.zipCode || !address.street || !address.number || !address.city || !address.state ? 'Preencha os campos obrigatórios.' : ''; if (error.value) return; store.nextStep(); router.push('/cadastro/tamanho') }
</script>
<template><section><h1 class="text-3xl font-medium tracking-tight sm:text-4xl">Onde sua empresa fica?</h1><p class="mt-5 leading-7 text-neutral-600">Informe o CEP para preencher o endereço automaticamente.</p><div class="mt-10 space-y-5"><label class="block"><span class="text-sm font-medium">CEP</span><input :value="store.state.address.zipCode" inputmode="numeric" placeholder="00000-000" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4 outline-none focus:border-neutral-900 focus:ring-2 focus:ring-lime-200" @input="store.updateAddress({ zipCode: maskCep(($event.target as HTMLInputElement).value) }); lookup()" /></label><div class="grid gap-5 sm:grid-cols-[1fr_150px]"><label class="block"><span class="text-sm font-medium">Rua</span><input v-model="store.state.address.street" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4" /></label><label class="block"><span class="text-sm font-medium">Número</span><input v-model="store.state.address.number" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4" /></label></div><label class="block"><span class="text-sm font-medium">Complemento</span><input v-model="store.state.address.complement" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4" /></label><div class="grid gap-5 sm:grid-cols-2"><label class="block"><span class="text-sm font-medium">Bairro</span><input v-model="store.state.address.neighborhood" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4" /></label><label class="block"><span class="text-sm font-medium">Cidade</span><input v-model="store.state.address.city" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4" /></label></div><label class="block"><span class="text-sm font-medium">Estado</span><input v-model="store.state.address.state" maxlength="2" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4 uppercase" /></label><p v-if="loading" class="text-sm text-neutral-500">Consultando CEP...</p><p v-if="error" class="text-sm text-red-600">{{ error }}</p><BaseButton class="min-h-[56px] w-full text-base sm:min-h-[68px] sm:text-lg" @click="next">Continuar</BaseButton></div></section></template>
